<template>
  <div class="app-page"><div class="app-page-inner-wide">
    <section class="app-page-header flex flex-col gap-5 lg:flex-row lg:items-end lg:justify-between"><div><h1 class="app-title">{{ t('screeners.title') }}</h1></div><button type="button" class="app-button-primary" @click="newScreener">{{ t('screeners.new') }}</button></section>
    <div v-if="error" class="border border-rose-200 bg-rose-50 px-4 py-3 text-sm text-rose-700 dark:border-rose-900 dark:bg-rose-950/30 dark:text-rose-200" role="alert">{{ error }}</div>
    <div class="grid gap-5 xl:grid-cols-[18rem_minmax(0,1fr)]">
      <aside class="app-panel"><div class="app-panel-header"><h2 class="app-section-title">{{ t('screeners.saved') }}</h2><label class="mt-3 flex items-center gap-2 text-sm app-muted"><input v-model="includeArchived" type="checkbox" @change="loadScreeners" />{{ t('screeners.includeArchived') }}</label></div><div class="space-y-2 p-3"><button v-for="item in screeners" :key="item.id" type="button" class="w-full border-l-2 px-3 py-3 text-left" :class="active?.id===item.id?'border-emerald-700 bg-emerald-50 dark:bg-emerald-950/20':'border-transparent hover:bg-stone-50 dark:hover:bg-slate-700/40'" @click="select(item)"><span class="block font-semibold">{{ item.name }}</span><span v-if="item.archivedAt || item.description" class="mt-1 block text-xs app-muted">{{ item.archivedAt ? t('screeners.archived') : item.description }}</span></button><p v-if="!screeners.length" class="p-5 text-sm app-muted">{{ t('screeners.empty') }}</p></div></aside>
      <main class="space-y-5">
        <section v-if="editing" class="app-panel p-5"><div class="flex items-center justify-between"><h2 class="app-section-title">{{ active ? t('screeners.edit') : t('screeners.create') }}</h2><button type="button" class="text-sm app-muted underline" @click="editing=false">{{ t('screeners.cancel') }}</button></div><form class="mt-5 space-y-4" @submit.prevent="save"><div class="grid gap-3 md:grid-cols-2"><label class="space-y-1"><span class="label">{{ t('screeners.name') }}</span><input v-model.trim="form.name" class="app-control w-full" required /></label><label class="space-y-1"><span class="label">{{ t('screeners.description') }}</span><input v-model.trim="form.description" class="app-control w-full" /></label></div><div class="grid gap-3 sm:grid-cols-2 xl:grid-cols-4"><label class="space-y-1"><span class="label">Market</span><select v-model="form.market" class="app-control w-full"><option value="all">All</option><option value="spot">Spot</option><option value="usdm">USD-M</option></select></label><label class="space-y-1"><span class="label">{{ t('screeners.minChange') }}</span><input v-model="form.minChange" type="number" step="any" class="app-control w-full" /></label><label class="space-y-1"><span class="label">{{ t('screeners.minVolume') }}</span><input v-model="form.minVolume" type="number" step="any" class="app-control w-full" /></label><label class="space-y-1"><span class="label">{{ t('screeners.breakoutScore') }}</span><input v-model="form.breakout" type="number" min="0" max="100" class="app-control w-full" /></label><label class="space-y-1"><span class="label">{{ t('screeners.maxFunding') }}</span><input v-model="form.maxFunding" type="number" step="any" class="app-control w-full" /></label><label class="space-y-1"><span class="label">{{ t('screeners.minOi') }}</span><input v-model="form.minOi" type="number" step="any" class="app-control w-full" /></label><label class="space-y-1"><span class="label">{{ t('screeners.minRsi') }}</span><input v-model="form.minRsi" type="number" min="0" max="100" step="any" class="app-control w-full" /></label><label class="space-y-1"><span class="label">{{ t('screeners.maxRsi') }}</span><input v-model="form.maxRsi" type="number" min="0" max="100" step="any" class="app-control w-full" /></label><label class="flex items-center gap-2 pt-6"><input v-model="form.includeWeb3" type="checkbox" />{{ t('screeners.includeWeb3') }}</label><label class="space-y-1"><span class="label">{{ t('screeners.web3Chain') }}</span><input v-model.trim="form.web3ChainId" class="app-control w-full" placeholder="56" /></label><label class="space-y-1"><span class="label">{{ t('screeners.maxWeb3Risk') }}</span><input v-model="form.maxWeb3Risk" type="number" min="0" max="5" class="app-control w-full" /></label><label class="space-y-1 xl:col-span-2"><span class="label">{{ t('screeners.symbols') }}</span><input v-model.trim="form.symbols" class="app-control w-full" placeholder="BTCUSDT, ETHUSDT, token address" /></label></div><button type="submit" class="app-button-primary" :disabled="saving">{{ saving ? t('screeners.saving') : t('screeners.save') }}</button></form></section>
        <template v-if="active && !editing">
          <section class="app-panel p-5"><div class="flex flex-col gap-4 lg:flex-row lg:items-start lg:justify-between"><div><h2 class="text-xl font-semibold">{{ active.name }}</h2><p v-if="active.description" class="mt-2 text-sm app-muted">{{ active.description }}</p><p class="mt-3 text-xs app-muted">{{ filterSummary }}</p></div><div class="flex flex-wrap gap-2"><button type="button" class="app-button-secondary" @click="editActive">{{ t('screeners.edit') }}</button><button type="button" class="app-button-secondary" @click="toggleArchive">{{ active.archivedAt?t('screeners.restore'):t('screeners.archive') }}</button><button type="button" class="app-button-primary" :disabled="running || !!active.archivedAt" @click="run()">{{ running?t('screeners.running'):t('screeners.runNow') }}</button></div></div><div class="mt-5 flex flex-col gap-2 sm:flex-row sm:items-end"><label class="space-y-1"><span class="label">{{ t('screeners.replayAt') }}</span><input v-model="replayAt" type="datetime-local" class="app-control" /></label><button type="button" class="app-button-secondary" :disabled="running || !replayAt" @click="run(replayAt)">{{ t('screeners.replay') }}</button></div></section>
          <section v-if="lastRun" class="app-panel overflow-hidden"><div class="app-panel-header flex items-center justify-between"><div><h2 class="app-section-title">{{ lastRun.historicalReplay?t('screeners.historicalResult'):t('screeners.currentResult') }}</h2><p class="mt-1 text-xs app-muted">{{ dateTime(lastRun.snapshotAsOf) }}</p></div><span class="app-chip">{{ lastRun.resultCount }}</span></div><div class="app-table-scroll"><table class="min-w-[1100px] w-full text-sm"><thead class="app-table-head"><tr><th class="px-3 py-2 text-left">Market</th><th class="px-3 py-2 text-left">Symbol</th><th class="px-3 py-2 text-right">Price</th><th class="px-3 py-2 text-right">24h</th><th class="px-3 py-2 text-right">Volume</th><th class="px-3 py-2 text-right">Funding</th><th class="px-3 py-2 text-right">Breakout</th><th class="px-3 py-2 text-right">OI 1h</th><th class="px-3 py-2 text-right">RSI</th><th class="px-3 py-2 text-right">Web3 heat</th><th class="px-3 py-2 text-right">Web3 risk</th></tr></thead><tbody><tr v-for="(row,index) in lastRun.resultItems || []" :key="`${String(row.symbol)}-${index}`" class="app-table-row"><td class="px-3 py-3">{{ row.market }}</td><td class="px-3 py-3 font-semibold"><router-link :to="assetLink(row)" class="text-emerald-700 hover:underline dark:text-emerald-300">{{ row.symbol }}</router-link></td><td class="px-3 py-3 text-right">{{ num(row.lastPrice) }}</td><td class="px-3 py-3 text-right">{{ pct(row.priceChangePct) }}</td><td class="px-3 py-3 text-right">{{ num(row.quoteVolume) }}</td><td class="px-3 py-3 text-right">{{ pct(row.fundingRatePct) }}</td><td class="px-3 py-3 text-right">{{ num(row.breakoutScore) }}</td><td class="px-3 py-3 text-right">{{ pct(row.oiChange1hPct) }}</td><td class="px-3 py-3 text-right">{{ num(row.rsi) }}</td><td class="px-3 py-3 text-right">{{ num(row.heatScore) }}</td><td class="px-3 py-3 text-right">{{ num(row.web3RiskLevel) }}</td></tr><tr v-if="!lastRun.resultCount"><td colspan="11" class="p-8 text-center app-muted">{{ t('screeners.noMatches') }}</td></tr></tbody></table></div></section>
          <section class="app-panel"><div class="app-panel-header"><h2 class="app-section-title">{{ t('screeners.history') }}</h2></div><div class="divide-y divide-stone-200 dark:divide-slate-700"><button v-for="item in runs" :key="item.id" type="button" class="flex w-full items-center justify-between p-4 text-left hover:bg-stone-50 dark:hover:bg-slate-700/30" @click="lastRun=item"><span>{{ dateTime(item.snapshotAsOf) }}</span><span class="app-chip">{{ item.resultCount }}</span></button><p v-if="!runs.length" class="p-8 text-center app-muted">{{ t('screeners.noHistory') }}</p></div></section>
        </template>
        <section v-else-if="!editing" class="app-panel p-12 text-center app-muted">{{ t('screeners.choose') }}</section>
      </main>
    </div>
  </div></div>
</template>

<script setup lang="ts">
import { computed, onMounted, reactive, ref } from 'vue'; import { useI18n } from 'vue-i18n'; import { researchApi } from '@/modules/research'; import type { MarketScreenerRunResponse, SavedMarketScreenerResponse } from '@/modules/research/contracts'
const { t }=useI18n(); const screeners=ref<SavedMarketScreenerResponse[]>([]); const active=ref<SavedMarketScreenerResponse|null>(null); const runs=ref<MarketScreenerRunResponse[]>([]); const lastRun=ref<MarketScreenerRunResponse|null>(null); const includeArchived=ref(false); const editing=ref(false); const saving=ref(false); const running=ref(false); const error=ref(''); const replayAt=ref('')
const blank=()=>({name:'',description:'',market:'all' as 'all'|'spot'|'usdm',minChange:'',minVolume:'',breakout:'',maxFunding:'',minOi:'',minRsi:'',maxRsi:'',includeWeb3:false,web3ChainId:'',maxWeb3Risk:'',symbols:''}); const form=reactive(blank())
const optional=(value:string)=>value===''?null:Number(value); const body=()=>({name:form.name,description:form.description,filters:{market:form.market,quoteAsset:'USDT',minPriceChangePct:optional(form.minChange),maxPriceChangePct:null,minQuoteVolume:optional(form.minVolume),maxFundingRatePct:optional(form.maxFunding),minBreakoutScore:optional(form.breakout),minOiChange1hPct:optional(form.minOi),minRsi:optional(form.minRsi),maxRsi:optional(form.maxRsi),includeWeb3:form.includeWeb3,web3ChainId:form.web3ChainId||null,maxWeb3RiskLevel:optional(form.maxWeb3Risk),symbols:form.symbols.split(',').map(v=>v.trim()).filter(Boolean),limit:100}})
const loadScreeners=async()=>{try{const response=await researchApi.listScreeners(includeArchived.value);screeners.value=response.items||[];if(active.value){active.value=screeners.value.find(v=>v.id===active.value?.id)||null}}catch(reason){error.value=reason instanceof Error?reason.message:String(reason)}}
const select=async(item:SavedMarketScreenerResponse)=>{active.value=item;editing.value=false;lastRun.value=null;const response=await researchApi.listScreenerRuns(item.id);runs.value=response.items||[];lastRun.value=runs.value[0]||null}
const newScreener=()=>{active.value=null;Object.assign(form,blank());editing.value=true}; const editActive=()=>{if(!active.value)return;const f=active.value.filters;Object.assign(form,{name:active.value.name,description:active.value.description,market:f.market,minChange:f.minPriceChangePct??'',minVolume:f.minQuoteVolume??'',breakout:f.minBreakoutScore??'',maxFunding:f.maxFundingRatePct??'',minOi:f.minOiChange1hPct??'',minRsi:f.minRsi??'',maxRsi:f.maxRsi??'',includeWeb3:f.includeWeb3,web3ChainId:f.web3ChainId??'',maxWeb3Risk:f.maxWeb3RiskLevel??'',symbols:(f.symbols||[]).join(', ')});editing.value=true}
const save=async()=>{saving.value=true;try{const saved=active.value?await researchApi.updateScreener(active.value.id,{...body(),expectedVersion:active.value.version}):await researchApi.createScreener(body());await loadScreeners();active.value=saved;editing.value=false;await select(saved)}catch(reason){error.value=reason instanceof Error?reason.message:String(reason)}finally{saving.value=false}}
const toggleArchive=async()=>{if(!active.value)return;active.value=await researchApi.setScreenerArchived(active.value.id,active.value.version,!active.value.archivedAt);await loadScreeners()}; const run=async(asOf?:string)=>{if(!active.value)return;running.value=true;try{lastRun.value=await researchApi.runScreener(active.value.id,asOf?new Date(asOf).toISOString():undefined);const response=await researchApi.listScreenerRuns(active.value.id);runs.value=response.items||[]}catch(reason){error.value=reason instanceof Error?reason.message:String(reason)}finally{running.value=false}}
const filterSummary=computed(()=>active.value?JSON.stringify(active.value.filters):'');const dateTime=(v:string)=>new Date(v).toLocaleString();const asNumber=(v:unknown)=>typeof v==='number'?v:Number(v);const num=(v:unknown)=>Number.isFinite(asNumber(v))?new Intl.NumberFormat(undefined,{maximumFractionDigits:4}).format(asNumber(v)):'--';const pct=(v:unknown)=>Number.isFinite(asNumber(v))?`${asNumber(v).toFixed(2)}%`:'--';const displaySymbol=(v:unknown)=>{const text=String(v||'');return text.endsWith('USDT')?`${text.slice(0,-4)}/USDT`:text};const assetLink=(row:Record<string,unknown>)=>row.market==='web3'?{path:`/research/assets/${encodeURIComponent(String(row.contractAddress||row.symbol))}`,query:{asset_class:'web3',chain_id:String(row.chainId||''),platform:String(row.platform||'')}}:`/research/assets/${encodeURIComponent(displaySymbol(row.symbol))}`;onMounted(loadScreeners)
</script>
